            count = sum(v == color for line in grid for v in line)
            candidates.append((count, "col", c))

    _, direction, sep = min(candidates)

    if direction == "row":
        first, second = grid[:sep], grid[sep + 1:]
    else:
        first = [row[:sep] for row in grid]
        second = [row[sep + 1:] for row in grid]

    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    bg1, bg2 = background(first), background(second)
    rows = min(len(first), len(second))
    cols = min(len(first[0]), len(second[0]))

    return [
        [2 if first[r][c] != bg1 and second[r][c] != bg2 else 0
         for c in range(cols)]
        for r in range(rows)
    ]
